import{_ as i,C as n,o as l,c as d,j as a,a as o,E as r,a2 as s}from"./chunks/framework.DrWxItG4.js";const y=JSON.parse('{"title":"0x07 TILE_ACTIVATE_REQUEST","description":"","frontmatter":{},"headers":[],"relativePath":"packets/07-tile-activate-request.md","filePath":"packets/07-tile-activate-request.md"}'),c={name:"packets/07-tile-activate-request.md"};function h(u,e,p,g,f,x){const t=n("Badge");return l(),d("div",null,[e[0]||(e[0]=a("h1",{id:"_0x07-tile-activate-request",tabindex:"-1"},[o("0x07 TILE_ACTIVATE_REQUEST "),a("a",{class:"header-anchor",href:"#_0x07-tile-activate-request","aria-label":'Permalink to "0x07 TILE_ACTIVATE_REQUEST"'},"​")],-1)),r(t,{type:"info",text:"GAME_PACKET (4)"}),e[1]||(e[1]=o()),r(t,{type:"info",text:"client → server"}),e[2]||(e[2]=o()),r(t,{type:"tip",text:"confirmed"}),e[3]||(e[3]=a("h2",{id:"what-the-client-sends",tabindex:"-1"},[o("What the client sends "),a("a",{class:"header-anchor",href:"#what-the-client-sends","aria-label":'Permalink to "What the client sends"'},"​")],-1)),r(t,{type:"tip",text:"decompiled from the 5.60 client"}),e[4]||(e[4]=s('<p>The client never handles this type; it <strong>sends</strong> it. It asks the server to activate a tile: enter a door or portal, touch a checkpoint, a race flag, a pickup and so on. Every send goes through <code>0x1381730</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><code>type</code></td><td>0x07</td></tr><tr><td><code>tileX</code>, <code>tileY</code></td><td>the tile (tile+0x54, +0x55)</td></tr><tr><td>everything else</td><td>0 (no <code>netID</code>, no position)</td></tr></tbody></table><p>Sent reliable, no extra data.</p><h3 id="when-it-s-sent" tabindex="-1">When it&#39;s sent <a class="header-anchor" href="#when-it-s-sent" aria-label="Permalink to &quot;When it&#39;s sent&quot;">​</a></h3><ul><li><strong>Entering a door</strong> (<code>0x13035e4</code>): by walking into a tile of action type 26 (portals: Orange Portal, Blue Portal, Hellgate, Time-Space Rupture...), or of action type 43 (Sungate) when a value at <code>0x11b25a4</code>+0x260 is above 6; by tapping the door you stand on with the Fist; or with the punch key while on it. Before sending, the client: <ul><li>refuses with &quot;You must complete the tutorial first!&quot; (at most every 1.5 s) when feature 6 isn&#39;t unlocked (<code>0x1444c80(6)</code>);</li><li>refuses the Main Door (6) while avatar+0x175 bit 7 is set, and the Rune Carved Door (9358) unless you wear Magic Stones (9356);</li><li>zooms the camera, freezes you until the server answers (avatar+0x128), closes open dialogs, and for doors other than the Main Door shows &quot;Entering world&quot;.</li></ul></li><li><strong>Walking into a tile</strong> (<code>0x13002b4</code>, every frame), once per tile until you step on another one (avatar+0x254 holds the last tile index; <code>OnSetPos</code> resets it): <ul><li>Challenge End Flag (3808), Blarney Stone (1508), Great Legendary Orb (1792), Great Wolf Totem (2994), Finale Claim 1-9 (8776-8792), Icy Heart Pickup (3212);</li><li>Race Start Flag (428) when you aren&#39;t racing, Race End Flag (430) when you are (avatar+0x68);</li><li>tiles of action type 94 (Valhowla Treasure...) that aren&#39;t already &quot;on&quot; (tile flag 0x40);</li><li>Steam Stomper (3270) when its state allows it (<code>0x15b241c</code> false, <code>0x15b244c</code> ≥ 1) and you fall onto it faster than ¾ of a physics constant; Steam Revolver (3496) under the same state checks while you move;</li><li>adventure tiles: The Adventure Begins (4722), Tomb Robber (4742), Adventure&#39;s End (4740, only after an adventure flag at avatar+0x2eb is set), the Adventure Brazier (4704) while you carry the Adventure Item - Torch (1702), and the Adventure Pedestal (4708) while you carry the Golden Idol (1698). Brazier and Pedestal are skipped while a flag at avatar+0x2e8 / +0x2e9 is set (probably &quot;already done&quot;);</li><li>team games, while you&#39;re on a team (avatar+0x26d ≤ 4): a Game Flag (1622) or Game Egg (5992) of another team (its tile extra&#39;s team byte, +0x60), and a Game Goal (1658) or Game Goal Egg Basket (5998) of your team;</li><li>a checkpoint (action type 27) that isn&#39;t your current one (avatar+0x25c).</li></ul></li><li><strong>Landing on a powered Steam Launcher</strong> (3498, tile flag 0x40, <code>0x131092c</code>): the client launches you, clears the flag and sends 0x07.</li><li><strong>Tapping with the Fist</strong> (<code>0x13a70f8</code>) an Angry Adventure Gorilla (4712) that is &quot;on&quot; while you carry the Adventure Item - Banana (1700), or item 7962 while you carry item 7960.</li><li><strong>A moving world object reaching a checkpoint</strong> (<code>0x12c5640</code>, world objects updated by <code>0x12b5c18</code>): when the object enters a new tile of action type 27 (Checkpoint, Flower Checkpoint...). Probably an object you control; which items use it wasn&#39;t traced.</li></ul><p><small>Sender: <code>0x1381730</code>; callers <code>0x13035e4</code>, <code>0x13002b4</code>, <code>0x1303a18</code>, <code>0x131092c</code>, <code>0x13a70f8</code>, <code>0x12c5640</code>.</small></p><h2 id="header-fields-used" tabindex="-1">Header fields used <a class="header-anchor" href="#header-fields-used" aria-label="Permalink to &quot;Header fields used&quot;">​</a></h2><p>Offsets are from the <a href="/gtps-guide/guide/game-packet">game packet header</a>. Fields not listed are 0.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tileX / tileY</code></td><td>the tile you activated (door, portal, ...)</td></tr></tbody></table><h2 id="gurotopia" tabindex="-1">gurotopia <a class="header-anchor" href="#gurotopia" aria-label="Permalink to &quot;gurotopia&quot;">​</a></h2><p><code>include/gamePacket/tile_activate.cpp</code>: doors and portals warp you.</p><h2 id="official-client" tabindex="-1">Official client <a class="header-anchor" href="#official-client" aria-label="Permalink to &quot;Official client&quot;">​</a></h2><p><strong>Received:</strong> ignored (falls to the switch&#39;s default).</p><p><strong>Sent:</strong> <code>0x1381790</code> sets the type to 7.</p>',14))])}const b=i(c,[["render",h]]);export{y as __pageData,b as default};
